#!/usr/bin/env python3
"""Build the shipment summary described in /app/docs/summary-format.md.

Usage: summarize.py DATA_DIR OUT_FILE
"""
import csv
import gzip
import io
import json
import os
import re
import sys
import xml.etree.ElementTree as ET
from datetime import date, datetime, timedelta, timezone
from decimal import Decimal, ROUND_HALF_UP
from fractions import Fraction

PRIORITY = ["central", "south", "east", "river", "north", "west", "harbor", "lakeside"]

KG = {
    "kg": Fraction(1),
    "g": Fraction(1, 1000),
    "lb": Fraction(45359237, 100000000),
    "oz": Fraction(28349523125, 1000000000000),
}
UNIT_ALIASES = {
    "kg": "kg", "kgs": "kg", "kilogram": "kg", "kilograms": "kg",
    "g": "g", "gram": "g", "grams": "g",
    "lb": "lb", "lbs": "lb", "pound": "lb", "pounds": "lb",
    "oz": "oz", "ounce": "oz", "ounces": "oz",
}

COUNTED = {"delivered", "delivered_late"}

FW_STATUS = {"D": "delivered", "L": "delivered_late", "C": "cancelled",
             "R": "returned", "H": "held"}
HARBOR_STATUS = {"DLV": "delivered", "DLL": "delivered_late", "CAN": "cancelled",
                 "RET": "returned", "HLD": "held"}

MONTHS = {m: i + 1 for i, m in enumerate(
    ["jan", "feb", "mar", "apr", "may", "jun", "jul", "aug", "sep", "oct", "nov", "dec"])}

# ---------------------------------------------------------------- helpers


def warn(msg):
    sys.stderr.write("warning: %s\n" % msg)


def read_text(path):
    """Read an export as text: gzip, BOM, charset directive."""
    with open(path, "rb") as fh:
        raw = fh.read()
    if raw[:2] == b"\x1f\x8b":
        raw = gzip.decompress(raw)
    enc = None
    if raw[:3] == b"\xef\xbb\xbf":
        enc, raw = "utf-8", raw[3:]
    elif raw[:2] == b"\xff\xfe":
        enc, raw = "utf-16-le", raw[2:]
    elif raw[:2] == b"\xfe\xff":
        enc, raw = "utf-16-be", raw[2:]
    else:
        m = re.search(rb"^[ \t]*#[ \t]*charset[ \t]*:[ \t]*([A-Za-z0-9_.:-]+)", raw[:4096],
                      re.M | re.I)
        if m:
            enc = m.group(1).decode("ascii")
        else:
            m = re.match(rb"\s*<\?xml[^>]*encoding=[\"']([A-Za-z0-9_.:-]+)[\"']", raw[:512])
            if m:
                enc = m.group(1).decode("ascii")
    try:
        return raw.decode(enc or "utf-8")
    except (LookupError, UnicodeDecodeError):
        return raw.decode("utf-8", errors="replace")


def parse_id(s):
    if s is None:
        return None
    m = re.match(r"^\s*SH\D*(\d+)\s*$", str(s), re.I)
    return int(m.group(1)) if m else None


def norm_type(s):
    s = (s or "").strip().lower()
    if s in ("", "n", "new"):
        return "new"
    if s in ("c", "cor", "corr", "correction", "amend", "amendment"):
        return "correction"
    if s in ("v", "void"):
        return "void"
    return None


def norm_status(s):
    return re.sub(r"[\s_-]+", "_", (s or "").strip().lower())


def norm_unit(s):
    if s is None:
        return None
    return UNIT_ALIASES.get(str(s).strip().lower().rstrip("."))


def parse_number(s, decimal_comma):
    s = s.strip().replace(" ", "")
    if decimal_comma:
        s = s.replace(".", "").replace(",", ".")
    else:
        s = s.replace(",", "")
    return Fraction(Decimal(s))


def weight_kg(value, unit, decimal_comma):
    """value: string possibly with a unit suffix; unit: fallback unit name."""
    s = str(value).strip()
    m = re.match(r"^([-+0-9.,\s]+?)\s*([A-Za-z]+)?\s*$", s)
    if not m:
        raise ValueError("bad weight %r" % value)
    num, u = m.group(1), norm_unit(m.group(2)) if m.group(2) else None
    if m.group(2) and u is None:
        raise ValueError("bad weight unit %r" % value)
    u = u or unit
    if u is None:
        raise ValueError("no unit for weight %r" % value)
    return parse_number(num, decimal_comma) * KG[u]


def date_form(s):
    """Reduce a declared date form to YMD / DMY / MDY / SERIAL / None."""
    f = re.sub(r"[^A-Za-z]", "", s or "").upper()
    if f in ("ISO", "YMD", "YYYYMMDD"):
        return "YMD"
    if f in ("DMY", "DDMMYYYY"):
        return "DMY"
    if f in ("MDY", "MMDDYYYY"):
        return "MDY"
    if f == "SERIAL":
        return "SERIAL"
    return None


ISO_DT = re.compile(
    r"^(\d{4})-(\d{1,2})-(\d{1,2})(?:[T ](\d{1,2}):(\d{2})(?::(\d{2})(?:[.,]\d+)?)?"
    r"\s*(Z|z|[+-]\d{2}(?::?\d{2})?)?)?$")


def parse_date(value, form):
    """Return the UTC calendar date of a ship date / ship time string."""
    s = str(value).strip()
    m = ISO_DT.match(s)
    if m:
        y, mo, d = int(m.group(1)), int(m.group(2)), int(m.group(3))
        if m.group(4) is None:
            return date(y, mo, d)
        dt = datetime(y, mo, d, int(m.group(4)), int(m.group(5)), int(m.group(6) or 0))
        tz = m.group(7)
        if tz and tz not in ("Z", "z"):
            sign = -1 if tz[0] == "-" else 1
            digits = tz[1:].replace(":", "")
            off = timedelta(hours=int(digits[:2]), minutes=int(digits[2:] or 0))
            dt = dt - sign * off
        return dt.date()
    m = re.match(r"^(\d{1,2})[ -]([A-Za-z]{3})[A-Za-z]*[ -](\d{4})$", s)
    if m and m.group(2).lower() in MONTHS:
        return date(int(m.group(3)), MONTHS[m.group(2).lower()], int(m.group(1)))
    if form == "SERIAL" or re.fullmatch(r"\d{5}(\.\d+)?", s):
        return date(1899, 12, 30) + timedelta(days=int(float(s)))
    nums = re.findall(r"\d+", s)
    if len(nums) == 1 and len(nums[0]) == 8:
        n = nums[0]
        nums = [n[:4], n[4:6], n[6:]] if form in (None, "YMD") else [n[:2], n[2:4], n[4:]]
    if len(nums) != 3:
        raise ValueError("bad date %r" % value)
    a, b, c = (int(x) for x in nums)
    if len(nums[0]) == 4:
        return date(a, b, c)
    if form == "MDY":
        return date(c, a, b)
    return date(c, b, a)  # DMY


# ---------------------------------------------------------------- records


class Rec:
    __slots__ = ("num", "kind", "status", "kg", "day")

    def __init__(self, num, kind, status=None, kg=None, day=None):
        self.num, self.kind, self.status, self.kg, self.day = num, kind, status, kg, day


class Export:
    def __init__(self, depot, name):
        self.depot, self.name = depot, name
        self.seq = None
        self.records = []


DELIM = {
    "east": dict(delim=",", quoted=True, cols=["id", "type", "shipped", "gross", "net", "status", "note"],
                 id="id", type="type", date="shipped", weight="gross", status="status",
                 form="YMD", unit="kg", comma=False),
    "lakeside": dict(delim=",", quoted=True,
                     cols=["id", "kind", "booked", "shipped", "gross_kg", "net_kg", "status"],
                     id="id", type="kind", date="shipped", weight="gross_kg", status="status",
                     form="YMD", unit="kg", comma=False),
    "harbor": dict(delim="|", quoted=False, cols=["rec", "ref", "date", "weight", "state"],
                   id="ref", type="rec", date="date", weight="weight", status="state",
                   form="YMD", unit=None, comma=False),
    "river": dict(delim="\t", quoted=False, cols=["t", "ref", "shipped", "weight", "status"],
                  id="ref", type="t", date="shipped", weight="weight", status="status",
                  form="MDY", unit=None, comma=False),
    "west": dict(delim=";", quoted=False, cols=["id", "typ", "shipped", "weight", "status", "note"],
                 id="id", type="typ", date="shipped", weight="weight", status="status",
                 form="DMY", unit=None, comma=True),
}
EXTRA_COLS = {"unit", "weight_unit"}


def split_records(text, quoted):
    """Yield ('comment', line) or ('row', fields_or_line) items."""
    lines = text.split("\n")
    i, n = 0, len(lines)
    while i < n:
        line = lines[i].rstrip("\r")
        i += 1
        if i == n and line == "":
            break
        if line.strip() == "":
            continue
        if line.startswith("#"):
            yield "comment", line
            continue
        if quoted:
            while line.count('"') % 2 == 1 and i < n:
                line += "\n" + lines[i]
                i += 1
            try:
                row = next(csv.reader([line], delimiter=","))
            except (csv.Error, StopIteration):
                row = line.split(",")
            yield "row", row
        else:
            yield "row", line


def parse_directive(line):
    m = re.match(r"^#\s*([A-Za-z][A-Za-z _-]*?)\s*:\s*(.*?)\s*$", line)
    if not m:
        return None
    return re.sub(r"[\s_-]+", " ", m.group(1).lower()), m.group(2)


def parse_delimited(depot, text, exp):
    cfg = DELIM[depot]
    colset = set(cfg["cols"]) | EXTRA_COLS
    hdr = None
    form = cfg["form"]
    unit_dir = cfg["unit"]
    comma = cfg["comma"]
    for kind, item in split_records(text, cfg["quoted"]):
        if kind == "comment":
            d = parse_directive(item)
            if d:
                name, val = d
                if name == "seq" and exp.seq is None:
                    mm = re.match(r"\d+", val)
                    if mm:
                        exp.seq = int(mm.group())
                elif name in ("dates", "date", "date format", "dateformat"):
                    f = date_form(val)
                    if f:
                        form = f
                elif name in ("unit", "weight unit", "weightunit"):
                    u = norm_unit(re.split(r"[\s(]", val.strip(), 1)[0])
                    if u:
                        unit_dir = u
            else:
                mm = re.search(r"\bseq\s*=\s*(\d+)", item)
                if mm and exp.seq is None:
                    exp.seq = int(mm.group(1))
            continue
        row = item if cfg["quoted"] else item.split(cfg["delim"])
        fields = [f.strip() for f in row]
        if all(f.lower() in colset for f in fields if f != "") and any(f != "" for f in fields) \
                and sum(1 for f in fields if f.lower() in colset) >= 2:
            hdr = [f.lower() for f in fields]
            continue
        if hdr is None:
            continue
        idx = {c: k for k, c in enumerate(hdr)}
        row_unit = None
        if len(fields) == len(hdr) + 1 and "unit" not in idx and "weight_unit" not in idx:
            wi = idx.get(cfg["weight"])
            pos = None
            if wi is not None and wi + 1 < len(fields) and norm_unit(fields[wi + 1]):
                pos = wi + 1
            else:
                for k, f in enumerate(fields):
                    if norm_unit(f) and f.lower() in UNIT_ALIASES:
                        pos = k
                        break
            if pos is not None:
                row_unit = norm_unit(fields[pos])
                del fields[pos]
        if len(fields) < len(hdr):
            fields += [""] * (len(hdr) - len(fields))

        def get(col):
            k = idx.get(col)
            return fields[k] if k is not None and k < len(fields) else ""

        num = parse_id(get(cfg["id"]))
        if num is None:
            continue  # trailer / total / count rows
        rtype = norm_type(get(cfg["type"]))
        if rtype is None:
            warn("%s: unknown record type %r" % (exp.name, get(cfg["type"])))
            continue
        if rtype == "void":
            exp.records.append(Rec(num, "void"))
            continue
        status = norm_status(get(cfg["status"]))
        if depot == "harbor":
            status = HARBOR_STATUS.get(get(cfg["status"]).strip().upper(), status)
        try:
            day = parse_date(get(cfg["date"]), form)
            unit = None
            wcol = cfg["weight"]
            m = re.search(r"_(kg|g|lb|oz)$", wcol)
            if m:
                unit = m.group(1)
            if unit is None:
                unit = norm_unit(get("unit") or get("weight_unit")) or row_unit or unit_dir
            kg = weight_kg(get(wcol), unit, comma)
        except (ValueError, ArithmeticError) as e:
            warn("%s: %s" % (exp.name, e))
            continue
        exp.records.append(Rec(num, rtype, status, kg, day))


def fw_parse(line, layout):
    if layout == "FW1":
        num, t, sd, w, st = line[0:9], line[9], line[10:17], line[17:25], line[25:26]
        day = (date(int(sd[:4]), 1, 1) + timedelta(days=int(sd[4:]) - 1)) if sd.strip() else None
        kg = Fraction(int(w)) * KG["g"] if w.strip() else Fraction(0)
    elif layout == "FW2":
        t, num, sd, w, st = line[0], line[1:10], line[10:18], line[18:26], line[26:27]
        day = date(int(sd[:4]), int(sd[4:6]), int(sd[6:8])) if sd.strip() else None
        kg = Fraction(int(w), 100) if w.strip() else Fraction(0)
    else:  # FW3
        num, sd, t, w, st = line[0:9], line[9:16], line[16], line[17:24], line[24:25]
        day = (date(int(sd[:4]), 1, 1) + timedelta(days=int(sd[4:]) - 1)) if sd.strip() else None
        kg = Fraction(int(w), 10) * KG["lb"] if w.strip() else Fraction(0)
    return parse_id(num), norm_type(t), FW_STATUS.get(st.strip().upper(), ""), kg, day


FW_LEN = {"FW1": 42, "FW2": 43, "FW3": 41}
FW_BY_LEN = {v: k for k, v in FW_LEN.items()}


def guess_layout(line, current):
    if re.match(r"^[NCV]SH\d", line):
        return "FW2"
    if re.match(r"^SH\d{7}[NCV]", line):
        return "FW1"
    if re.match(r"^SH\d{7}\d{7}[NCV]", line):
        return "FW3"
    return current


def parse_fixed(text, exp):
    layout = None
    for raw in text.split("\n"):
        line = raw.rstrip("\r")
        if line.strip() == "" or "\x0c" in line:
            continue
        if line.startswith("#"):
            m = re.match(r"^#\s*LAYOUT\s+(\S+)", line, re.I)
            if m:
                layout = m.group(1).upper()
            m = re.match(r"^#\s*SEQ\s+(\d+)", line, re.I)
            if m and exp.seq is None:
                exp.seq = int(m.group(1))
            continue
        if re.match(r"^\s*SOUTH DEPOT", line):
            continue
        lay = FW_BY_LEN.get(len(line))
        if lay is None:
            lay = guess_layout(line, layout)
            if lay is None:
                continue
            line = line.ljust(FW_LEN[lay])
        try:
            num, rtype, status, kg, day = fw_parse(line, lay)
        except (ValueError, OverflowError):
            continue
        if num is None or rtype is None:
            continue
        if rtype == "void":
            exp.records.append(Rec(num, "void"))
        else:
            exp.records.append(Rec(num, rtype, status, kg, day))


def local(tag):
    return tag.rsplit("}", 1)[-1]


def parse_xml(text, exp):
    text = re.sub(r"^\s*<\?xml[^>]*\?>", "", text, count=1)
    root = ET.fromstring(text.strip())
    try:
        exp.seq = int(root.get("seq"))
    except (TypeError, ValueError):
        pass
    root_unit = norm_unit(root.get("weight-unit") or root.get("weight_unit") or root.get("unit"))
    for el in root.iter():
        if local(el.tag) != "shipment":
            continue
        kids = {local(c.tag): c for c in el}

        def val(name):
            if el.get(name) is not None:
                return el.get(name)
            c = kids.get(name)
            return c.text.strip() if c is not None and c.text else None

        num = parse_id(val("id"))
        if num is None:
            continue
        rtype = norm_type(val("type"))
        if rtype is None:
            continue
        if rtype == "void":
            exp.records.append(Rec(num, "void"))
            continue
        try:
            day = parse_date(val("shipped"), None)
            w = kids.get("weight")
            unit = None
            if w is not None:
                unit = norm_unit(w.get("unit"))
            unit = unit or norm_unit(el.get("weight-unit") or el.get("weight_unit")) or root_unit
            kg = weight_kg(w.text, unit, False)
        except (ValueError, ArithmeticError, AttributeError, TypeError) as e:
            warn("%s: %s" % (exp.name, e))
            continue
        exp.records.append(Rec(num, rtype, norm_status(val("status")), kg, day))


def parse_jsonl(text, exp):
    default_unit = None
    for line in text.split("\n"):
        line = line.strip()
        if not line:
            continue
        try:
            obj = json.loads(line)
        except ValueError:
            continue
        for o in (obj if isinstance(obj, list) else [obj]):
            if not isinstance(o, dict):
                continue
            if "meta" in o and isinstance(o["meta"], dict):
                try:
                    if exp.seq is None:
                        exp.seq = int(o["meta"].get("seq"))
                except (TypeError, ValueError):
                    pass
                default_unit = norm_unit(o["meta"].get("unit") or o["meta"].get("weight_unit")) \
                    or default_unit
                continue
            num = parse_id(o.get("id"))
            if num is None:
                continue
            rtype = norm_type(o.get("kind"))
            if rtype is None:
                continue
            if rtype == "void":
                exp.records.append(Rec(num, "void"))
                continue
            try:
                day = parse_date(o.get("shipped_at") or o.get("shipped"), None)
                value = unit = None
                for k, v in o.items():
                    m = re.match(r"^weight_(kg|g|lb|oz)$", k, re.I)
                    if m:
                        value, unit = v, m.group(1).lower()
                        break
                if value is None and "weight" in o:
                    value = o["weight"]
                    unit = norm_unit(o.get("unit") or o.get("weight_unit")) or default_unit
                kg = weight_kg(str(value), unit, False)
            except (ValueError, ArithmeticError, TypeError) as e:
                warn("%s: %s" % (exp.name, e))
                continue
            exp.records.append(Rec(num, rtype, norm_status(o.get("status")), kg, day))


def parse_export(depot, path, name):
    exp = Export(depot, name)
    text = read_text(path)
    if depot in DELIM:
        parse_delimited(depot, text, exp)
    elif depot == "south":
        parse_fixed(text, exp)
    elif depot == "central":
        parse_xml(text, exp)
    elif depot == "north":
        parse_jsonl(text, exp)
    else:
        warn("unknown depot %r in %s" % (depot, name))
    return exp


