def money(frac):
    d = Decimal(frac.numerator) / Decimal(frac.denominator)
    # exact: use a precise context via Fraction arithmetic
    scaled = frac * 100
    q, r = divmod(scaled.numerator, scaled.denominator)
    if r * 2 >= scaled.denominator:
        q += 1
    return float(Decimal(q).scaleb(-2))


def main():
    data_dir, out_file = sys.argv[1], sys.argv[2]
    exports = {}
    for name in sorted(os.listdir(data_dir)):
        path = os.path.join(data_dir, name)
        if not os.path.isfile(path):
            continue
        depot = name.split("-", 1)[0]
        exports.setdefault(depot, [])
        try:
            exports[depot].append(parse_export(depot, path, name))
        except Exception as e:  # keep going on a broken export
            warn("%s: %s" % (name, e))

    corrections = resends = 0
    current = {}
    for depot, exps in exports.items():
        exps.sort(key=lambda e: (e.seq if e.seq is not None else -1, e.name))
        cur = {}
        for exp in exps:
            for r in exp.records:
                if r.kind == "new":
                    if r.num in cur:
                        resends += 1
                    else:
                        cur[r.num] = r
                elif r.kind == "correction":
                    cur[r.num] = r
                    corrections += 1
                elif r.kind == "void":
                    cur.pop(r.num, None)
                    corrections += 1
        current[depot] = cur

    order = {d: i for i, d in enumerate(PRIORITY)}
    owners = {}
    for depot in sorted(current, key=lambda d: order.get(d, len(order))):
