        if r.status not in COUNTED:
            continue
        depots[ds[0]][0] += 1
        depots[ds[0]][1] += r.kg
        key = "%04d-%02d" % (r.day.year, r.day.month)
        m = months.setdefault(key, [0, Fraction(0)])
        m[0] += 1
        m[1] += r.kg

    out = {
        "depots": {d: {"shipments": v[0], "total_kg": money(v[1])} for d, v in sorted(depots.items())},
        "months": {k: {"shipments": v[0], "total_kg": money(v[1])} for k, v in sorted(months.items())},
        "corrections_applied": corrections,
        "resends_dropped": resends,
        "handovers": handovers,
    }
    os.makedirs(os.path.dirname(os.path.abspath(out_file)), exist_ok=True)
    with open(out_file, "w") as fh:
        json.dump(out, fh, indent=2)
        fh.write("\n")


if __name__ == "__main__":
